import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"What is freshrss-mcp?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1787003086000}`),a={name:`guide/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="what-is-freshrss-mcp" tabindex="-1">What is freshrss-mcp? <a class="header-anchor" href="#what-is-freshrss-mcp" aria-label="Permalink to “What is freshrss-mcp?”">​</a></h1><p><a href="https://freshrss.org" target="_blank" rel="noreferrer">FreshRSS</a> is a self-hosted RSS and Atom aggregator. It exposes a Google Reader compatible API at <code>/api/greader.php</code>, which is how mobile readers like Reeder and FeedMe talk to it.</p><p><code>freshrss-mcp</code> puts that API behind the <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">Model Context Protocol</a>, so an assistant can answer &quot;what is new in my feeds?&quot;, summarise the morning&#39;s articles, clean up subscriptions, or mark a backlog as read.</p><h2 id="why-not-talk-to-the-api-directly" tabindex="-1">Why not talk to the API directly? <a class="header-anchor" href="#why-not-talk-to-the-api-directly" aria-label="Permalink to “Why not talk to the API directly?”">​</a></h2><p>Because the Google Reader API is a museum piece. It was reverse-engineered from a product Google shut down in 2013, and its vocabulary leaks through everywhere:</p><table tabindex="0"><thead><tr><th>The API wants</th><th>These tools take</th></tr></thead><tbody><tr><td><code>user/-/state/com.google/reading-list</code></td><td><code>stream: &quot;reading-list&quot;</code></td></tr><tr><td><code>user/-/label/News</code></td><td><code>category: &quot;News&quot;</code></td></tr><tr><td><code>feed/12</code></td><td><code>feed_id: 12</code></td></tr><tr><td><code>tag:google.com,2005:reader/item/0006218f8a2b1c40</code></td><td><code>&quot;1719238946946112&quot;</code></td></tr><tr><td><code>ot=1755388800</code> (unix seconds)</td><td><code>since: &quot;2026-08-17&quot;</code></td></tr><tr><td><code>ts</code> in microseconds, documented as nanoseconds</td><td>an ISO date</td></tr><tr><td>up to 500 000 characters of raw HTML per article</td><td>plain text, capped</td></tr></tbody></table><p>The article id case is the one that bites hardest: the API reports ids as hexadecimal item tags but its write endpoints match on the decimal row id, and the values exceed 2^53 — so parsing them as JavaScript numbers silently edits a <em>different</em> article. This server converts them through <code>BigInt</code>.</p><h2 id="what-it-does-not-do" tabindex="-1">What it does not do <a class="header-anchor" href="#what-it-does-not-do" aria-label="Permalink to “What it does not do”">​</a></h2><p><strong>There is no search.</strong> FreshRSS offers no full-text search over this API; the Google Reader endpoints filter by stream, read state and date only. <code>list_articles</code> therefore has no query parameter. Narrow with <code>feed_id</code>, <code>category</code>, <code>since</code> and <code>until</code>, then filter the returned articles yourself.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/guide/getting-started">Getting started</a> — enable the API and set an API password</li><li><a href="/guide/clients">Connecting clients</a> — Claude Code, Claude Desktop, Codex, Docker</li><li><a href="/guide/security">Security</a> — what the credentials grant and how feeds are treated</li></ul>`,11)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};